<script setup lang="ts">
import { feedbackRef, confirmAction, toast } from '../feedback'
import { onMounted, onBeforeUnmount, ref, computed } from 'vue'
import { locale, t } from '../i18n'
import BackupManager from './BackupManager.vue'
import RemoteStorageMaintenance from './RemoteStorageMaintenance.vue'
const props=defineProps<{csrfToken:string}>(),emit=defineEmits<{expired:[]}>()
const backup=ref({enabled:false,directory:'',time:'03:00',timezone:'Asia/Shanghai',keep:0}),cdn=ref({enabled:false,baseUrl:'',maxAge:60})
const timezoneNames: Record<string, string> = { UTC: '协调世界时', 'Asia/Shanghai': '中国上海', 'Asia/Hong_Kong': '中国香港', 'Asia/Taipei': '中国台北', 'Asia/Tokyo': '日本东京', 'Asia/Singapore': '新加坡', 'Europe/London': '英国伦敦', 'Europe/Paris': '法国巴黎', 'America/New_York': '美国纽约', 'America/Chicago': '美国芝加哥', 'America/Denver': '美国丹佛', 'America/Los_Angeles': '美国洛杉矶', 'Australia/Sydney': '澳大利亚悉尼' }
const timezoneOptions = computed(() => {
  const zones = ['UTC', 'Asia/Shanghai', 'Asia/Hong_Kong', 'Asia/Taipei', 'Asia/Tokyo', 'Asia/Singapore', 'Europe/London', 'Europe/Paris', 'America/New_York', 'America/Chicago', 'America/Denver', 'America/Los_Angeles', 'Australia/Sydney']
  if (!zones.includes(backup.value.timezone)) zones.push(backup.value.timezone)
  return zones.map(value => ({ value, label: timezoneLabel(value) }))
})
function timezoneLabel(zone: string) {
  try {
    const date = new Date()
    const name = new Intl.DateTimeFormat(locale.value, { timeZone: zone, timeZoneName: 'long' }).formatToParts(date).find(p => p.type === 'timeZoneName')?.value || zone
    const raw = new Intl.DateTimeFormat('en', { timeZone: zone, timeZoneName: 'longOffset' }).formatToParts(date).find(p => p.type === 'timeZoneName')?.value || 'GMT'
    return (timezoneNames[zone] ? t(timezoneNames[zone]) : name) + ' (' + (raw === 'GMT' ? 'UTC+00:00' : raw.replace('GMT', 'UTC')) + ')'
  } catch { return zone }
}
type Job={id:string;kind:string;state:string;startedAt:number;finishedAt:number;total:number;completed:number;failed:number;bytes:number;destination?:string;message?:string}
const job=ref<Job>(),files=ref<{hash:string;bytes:number}[]>([]),deleteRemote=ref(false),busy=ref(false),error = feedbackRef('error'),message = feedbackRef('success'),loaded=ref(false)
let timer:ReturnType<typeof setInterval>|undefined,active=true
async function load(){try{const r=await fetch('/api/admin/operations');if(!active)return;if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);if(job.value?.state==='running'&&d.job?.state!=='running')toast(d.job?.state==='completed'?'任务已完成。':'任务未全部完成，请查看执行结果。',d.job?.state==='completed'?'success':'error');job.value=d.job;if(!loaded.value){backup.value=d.backup;cdn.value=d.cdn;loaded.value=true}}catch{if(active)error.value='暂时无法读取运维设置'}}
async function save(){if(backup.value.keep>0&&!await confirmAction({title:'备份保留策略',message:t('后续备份成功后，只保留最近 {count} 份校验完整的程序备份。',{count:backup.value.keep}),danger:true}))return;busy.value=true;error.value='';message.value='';try{const r=await fetch('/api/admin/operations',{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:JSON.stringify({backup:backup.value,cdn:cdn.value})});if(r.status===401){emit('expired');return};if(!r.ok){const d=await r.json();throw new Error(d.error)};message.value='运维设置已保存。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function preview(){busy.value=true;error.value='';try{const r=await fetch('/api/admin/storage/orphans');if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);files.value=d.files;message.value=files.value.length?'':'没有可回收的孤立文件。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function run(kind:'backup'|'sync'|'gc'){if(busy.value)return;if(kind==='gc'&&!await confirmAction({title:'存储回收',message:t('回收 {count} 个孤立文件？',{count:files.value.length}),danger:true}))return;busy.value=true;error.value='';message.value='';try{const r=await fetch('/api/admin/operations/'+kind,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:JSON.stringify({hashes:kind==='gc'?files.value.map(f=>f.hash):[],deleteRemote:deleteRemote.value})});if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);job.value=d;toast('任务已开始。');if(kind==='gc')files.value=[]}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const stateNames:Record<string,string>={running:'执行中',completed:'已完成',completed_with_errors:'完成，但部分文件未处理',failed:'未完成'}
function bytes(n:number){return (n/1048576).toFixed(2)+' MiB'}
onMounted(()=>{void load();timer=setInterval(()=>{void load()},3000)})
onBeforeUnmount(()=>{active=false;if(timer)clearInterval(timer)})
</script>
<template><div class="operations-settings"><form class="settings-form" @submit.prevent="save"><fieldset :disabled="!loaded||busy"><section class="settings-section"><h3>{{ t('自动备份') }}</h3><label class="checkbox-label"><input v-model="backup.enabled" type="checkbox" />{{ t('启用定时备份') }}</label><label class="binding-field"><span>{{ t('独立备份目录') }}</span><input v-model="backup.directory" placeholder="D:\Backups\WishingSkin" :required="backup.enabled" /></label><label class="binding-field"><span>{{ t('每日备份时间') }}</span><input v-model="backup.time" type="time" required /></label><label class="binding-field"><span>{{ t('备份时区') }}</span><select v-model="backup.timezone" required><option v-for="zone in timezoneOptions" :key="zone.value" :value="zone.value">{{ zone.label }}</option></select></label><label class="binding-field"><span>{{ t('保留备份份数') }}</span><input v-model.number="backup.keep" type="number" min="0" max="1000" placeholder="0" /></label><p>{{ t('0 表示全部保留。仅清理本程序生成且校验完整的备份。') }}</p></section><section class="settings-section"><h3>CDN</h3><label class="checkbox-label"><input v-model="cdn.enabled" type="checkbox" />{{ t('启用公开材质 CDN') }}</label><label class="binding-field"><span>{{ t('CDN 地址') }}</span><input v-model="cdn.baseUrl" type="url" placeholder="https://cdn.example.com" :required="cdn.enabled" /></label><label class="binding-field"><span>{{ t('缓存上限（秒）') }}</span><input v-model.number="cdn.maxAge" type="number" min="1" max="60" required /></label><p class="password-rule">{{ t('仅加速已审核的公开材质。需将 /cdn/textures/ 回源到本站，并转发签名查询参数。下架后的缓存最多保留 60 秒。') }}</p></section><button class="primary-button">{{ t('保存运维设置') }}</button></fieldset></form><BackupManager :revision="job?.kind === 'backup' ? job.state + job.id : ''" :csrf-token="csrfToken" @expired="emit('expired')" /><section class="settings-section"><h3>{{ t('存储维护') }}</h3><p class="password-rule">{{ t('同步旧材质前需先启用对象存储插件。存储回收仅清理超过 1 小时且无任何数据库引用的孤立文件，不影响现有角色、衣柜和备份。') }}</p><div class="settings-actions"><button class="secondary-button" type="button" :disabled="busy||job?.state==='running'" @click="run('sync')">{{ t('同步旧材质到对象存储') }}</button><button class="secondary-button" type="button" :disabled="busy||job?.state==='running'||!backup.directory" @click="run('backup')">{{ t('立即备份（使用已保存设置）') }}</button><button class="secondary-button" type="button" :disabled="busy||job?.state==='running'" @click="preview">{{ t('预览可回收文件') }}</button></div><div v-if="files.length" class="orphan-preview"><p>{{ t('可回收 {count} 个文件，共 {bytes}。',{count:files.length,bytes:bytes(files.reduce((sum,f)=>sum+f.bytes,0))}) }}</p><details><summary>{{ t('文件清单') }}</summary><ul><li v-for="f in files" :key="f.hash"><code>{{ f.hash }}</code> {{ bytes(f.bytes) }}</li></ul></details><label class="checkbox-label"><input v-model="deleteRemote" type="checkbox" />{{ t('同时删除当前对象存储中同名的孤立副本') }}</label><button class="danger-button" type="button" :disabled="busy||job?.state==='running'" @click="run('gc')">{{ t('执行回收') }}</button></div><RemoteStorageMaintenance :csrf-token="csrfToken" :running="job?.state==='running'" @expired="emit('expired')" @started="job=$event" /><div v-if="job?.id" class="operation-status" role="status"><strong>{{ t(({sync:'材质同步',backup:'备份',gc:'存储回收','remote-gc':'远端存储回收'} as Record<string,string>)[job.kind]||job.kind) }} / {{ t(stateNames[job.state]||job.state) }}</strong><p>{{ t('完成 {done} / {total}，未处理 {failed}',{done:job.completed,total:job.total,failed:job.failed}) }}</p><p v-if="job.destination">{{ job.destination }}</p><p v-if="job.message">{{ t(job.message) }}</p></div></section></div></template>
